const stdout = String($json.stdout || '');
const match = stdout.match(/^BATCH_RESULT=(.+)$/m);
if (!match) throw new Error('Factory did not emit a batch report. Check Execute Command output.');
const report = JSON.parse(match[1]);
if (!report.ok && report.status !== 'needs_configuration') { const failures = (report.results || []).filter(row => row.status === 'failed').map(row => row.error); throw new Error(report.error || failures.join('; ') || 'Factory failed; inspect video-control.csv.'); }
// needs_broll (Quality mode waiting for Envato clips) is a normal result, not an error.
const rel = value => String(value || '').replace(/^\/files\/heygen-workflow\//, '');
const name = value => String(value || '').split(String.fromCharCode(92)).join('/').split('/').pop();
const lines = [];
for (const result of report.results || []) {
  const mix = result.broll_mix || {};
  if (result.status === 'done') {
    lines.push('Rendered ' + name(result.video) + ' (' + (report.broll_mode || 'quantity') + ' mode): ' + rel(result.output_video) + ' | B-roll: ' + (mix.video_shots ?? '?') + ' video, ' + (mix.real_photo_shots ?? 0) + ' real photo, ' + (mix.generated_still_shots ?? 0) + ' AI still');
    if (result.envato_needed) lines.push('  Optional: ' + result.missing_beats + ' moment(s) could use a better clip. List: ' + rel(result.envato_needed));
  } else if (result.status === 'needs_broll') {
    lines.push('NOT rendered (quality mode) ' + name(result.video) + ': ' + result.missing_beats + ' important moment(s) need a real video clip.');
    lines.push('  List: ' + rel(result.envato_needed) + ' | Drop clips in: ' + rel(result.broll_inbox) + ' | then run again.');
  }
  for (const moment of result.envato_moments || []) lines.push('  - ' + moment.time + ' ' + moment.show + (moment.search ? ' | search Envato: "' + moment.search + '"' : ''));
  const inbox = result.inbox_import;
  if (inbox && (inbox.imported.length || inbox.rejected.length)) lines.push('  Inbox: imported ' + inbox.imported.length + (inbox.imported.length ? ' (' + inbox.imported.map(c => c.asset_id).join(', ') + ')' : '') + ', rejected ' + inbox.rejected.length + (inbox.rejected.length ? ' (' + inbox.rejected.map(c => c.file + ': ' + c.reason).join('; ') + ')' : '') + (inbox.index_refresh ? ' | search index ' + inbox.index_refresh : ''));
}
const handled = new Set((report.results || []).map(result => name(result.video)));
for (const job of report.waiting_for_broll || []) if (!handled.has(name(job.video))) lines.push('Still waiting for clips: ' + name(job.video) + ' | list: ' + rel(job.envato_needed) + ' | inbox: ' + rel(job.inbox));
if (report.status === 'needs_configuration') lines.push('Missing configuration: ' + (report.missing_keys || []).join(', '));
report.summary = lines.join('\n') || (report.status === 'idle' ? 'No new video to process.' : 'Done.');
return [{ json: report }];
